// JavaScript/Node numerical probe (runs inside the buggy revision runtime)

function isNumber(x){ return typeof x === 'number' && Number.isFinite(x); }

const candidates=[
  {name:'factory_PINF_p0_5', call: ()=>{ const qf=require('@stdlib/stats/base/dists/poisson/quantile/factory'); const q=qf(NaN); return q(0.5); }},
];

// We will robustly import both top-level and factory APIs.
const quantileMain = (lam)=>{ const q=require('@stdlib/stats/base/dists/poisson/quantile'); return q(0.5, lam); };
const factory = require('@stdlib/stats/base/dists/poisson/quantile/factory');

function runOne(p, lam){
  const q = factory(lam);
  return q(p);
}

const tasks=[
  {key:'quantile_main_PINF_p0_5', p:0.5, lam:Infinity, mode:'main'},
  {key:'factory_PINF_p0_5', p:0.5, lam:Infinity, mode:'factory'},
  {key:'factory_PINF_p0_9', p:0.9, lam:Infinity, mode:'factory'},
  {key:'factory_huge_lambda_p0_9', p:0.9, lam:1e300, mode:'factory'},
  {key:'factory_huge_lambda_p0_1', p:0.1, lam:1e300, mode:'factory'},
];

// Execute with internal wall-clock guard: if quantile hangs, record {timeout:true}.
async function main(){
  const results={};

  const wallTimeoutMs = 3000; // keep probe short; defect is non-termination/very long

  function withTimeout(fn){
    return new Promise((resolve)=>{
      const t=setTimeout(()=>resolve({timeout:true}), wallTimeoutMs);
      try{
        const out = fn();
        clearTimeout(t);
        resolve({timeout:false, value: out});
      }catch(err){
        clearTimeout(t);
        resolve({timeout:false, error:String(err && err.message ? err.message : err)});
      }
    });
  }

  for(const task of tasks){
    const r = await withTimeout(()=>{
      if(task.mode==='main') return quantileMain(task.lam, task.p);
      return runOne(task.p, task.lam);
    });
    results[task.key]=r;
  }

  return results;
}

module.exports = main;

